  'This field': 'Este campo',
  'Full name': 'Nombre completo',
  'Date of birth': 'Fecha de nacimiento',
  'Place of birth': 'Lugar de nacimiento',
  'Country of residence': 'País de residencia',
  'Phone number': 'Número de teléfono',
  'Emirates ID number': 'Número del Emirates ID',
  'Description of your work': 'Descripción de su trabajo',
  // The lower-case phrases `payment-service` pastes into the "Still needed" list.
  'the country the account is held in': 'el país donde está la cuenta',
  'account holder name': 'el nombre del titular',
  'bank name': 'el nombre del banco',
  'account number': 'el número de cuenta',
